fn dist2(dx: i32, dy: i32) -> i32 {
    dx * dx + dy * dy
}

fn manhattan(dx: i32, dy: i32) -> i32 {
    let mut a: i32 = dx;
    if a < 0 { a = 0 - a; }
    let mut b: i32 = dy;
    if b < 0 { b = 0 - b; }
    a + b
}

fn in_circle(dx: i32, dy: i32, r: i32) -> i32 {
    if dist2(dx, dy) <= r * r { 1 } else { 0 }
}

fn wrap(v: i32, max: i32) -> i32 {
    let m: i32 = v % max;
    if m < 0 { m + max } else { m }
}

fn dims() -> i32 {
    (256 << 16) | 112
}

